package com.bank.fitness.constraint;

// A constraint the organization faces TODAY, and whether the current arch meets it.
public class Constraint {
    private final String name;
    private final boolean bindingToday;   // is this constraint actually hurting us now?
    private final boolean archSatisfies;  // does the existing architecture meet it?

    public Constraint(String name, boolean bindingToday, boolean archSatisfies) {
        this.name = name; this.bindingToday = bindingToday; this.archSatisfies = archSatisfies;
    }
    public String name() { return name; }
    public boolean bindingToday() { return bindingToday; }
    public boolean archSatisfies() { return archSatisfies; }
}
