package com.bank.fitness.fitness;

import com.bank.fitness.constraint.Constraint;
import java.util.List;
import java.util.logging.Logger;

// Scores the architecture against TODAY's constraints, not the original justification.
public class FitnessEvaluator {
    private static final Logger log = Logger.getLogger(FitnessEvaluator.class.getName());

    public String evaluate(List<Constraint> constraints) {
        boolean anyBindingUnmet = false;
        for (Constraint c : constraints) {
            if (c.bindingToday() && !c.archSatisfies()) {
                anyBindingUnmet = true;
                log.warning(() -> "BINDING + UNMET: " + c.name()
                        + " — architecture fails a constraint that hurts us today");
            } else if (c.bindingToday()) {
                log.info(() -> "BINDING + met: " + c.name());
            } else {
                log.fine(() -> "not binding today: " + c.name());
            }
        }
        if (anyBindingUnmet) {
            log.warning("RECOMMENDATION: REPLACE — a binding constraint is unmet");
            return "REPLACE";
        }
        log.info("RECOMMENDATION: KEEP — all binding constraints satisfied");
        return "KEEP";
    }
}
