package com.bank.fitness;

import com.bank.fitness.constraint.Constraint;
import com.bank.fitness.fitness.FitnessEvaluator;
import java.util.List;
import java.util.logging.*;

public class ArchFitnessDemo {
    private static final Logger log = Logger.getLogger(ArchFitnessDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        FitnessEvaluator evaluator = new FitnessEvaluator();

        // The settlement engine handles 10x traffic — throughput is MET and not the issue.
        // But evaluate against TODAY's constraints:
        List<Constraint> constraints = List.of(
            new Constraint("throughput",       true,  true),   // still scales fine
            new Constraint("change_velocity",  true,  false),  // features take months
            new Constraint("ownership",        true,  false),  // orphaned critical parts
            new Constraint("operability",      true,  false),  // one specialist can recover it
            new Constraint("infra_cost",       true,  false),  // cost grew disproportionately
            new Constraint("regulatory",       true,  false),  // cannot do per-customer erasure
            new Constraint("coin_sorting_need",false, true)    // solves a problem we no longer have
        );

        log.info("=== Architecture fitness vs TODAY's constraints (not 10x throughput) ===");
        String decision = evaluator.evaluate(constraints);
        log.info(() -> "DECISION: " + decision + " (throughput alone would have said KEEP)");
    }
}

